   Text="Spatial Wallpaper · 沙箱预览";AutoScaleMode=AutoScaleMode.None;Font=SystemFonts.MessageBoxFont;ClientSize=new Size(width+24,height+166);FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterScreen;
   start=ActionButton("StartPreview","开始预览",12,12,()=>StartAsync());stop=ActionButton("StopPreview","停止",104,12,()=>StopAsync());restart=ActionButton("RestartPreview","重新启动",196,12,()=>RestartAsync());
   var eyeLabel=new Label{Text="眼位",AutoSize=true,Location=new Point(302,19)};Controls.Add(eyeLabel);eyes=new ComboBox{Name="EyeMode",AccessibleName="预览眼位",DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(342,14),Width=154};eyes.Items.AddRange(new object[]{"默认眼位","鼠标移动","自动移动"});eyes.SelectedIndex=0;Controls.Add(eyes);
