  Button ActionButton(string name,string text,int x,int y,Func<Task> command){var button=new Button{Name=name,Text=text,Location=new Point(x,y),Size=new Size(84,30),UseVisualStyleBackColor=true};button.Click+=async(sender,args)=>{try{await command();}catch(OperationCanceledException cancelled)when(cancelled.CancellationToken.IsCancellationRequested||cancellation?.IsCancellationRequested==true){}catch(Exception error){LastError=error.GetBaseException().Message;UpdateState();}};Controls.Add(button);return button;}
