   }catch(Exception error){LastError=cancellation.IsCancellationRequested?null:error.GetBaseException().Message;try{await ReleasePresentation();}catch(Exception cleanup){LastError+="; cleanup:"+cleanup.GetBaseException().Message;State="Faulted";throw;}if(!cancellation.IsCancellationRequested)State="Faulted";throw;}
  }
