  void TickPreview(){if(State!="Running"||presentation==null)return;var shown=presentation.LastReceipt;if(shown!=null){lastReceipt=shown;status.Text="正在预览 · "+pixelsWide+" × "+pixelsHigh+" · 已呈现投影修订 "+shown["projection_revision"];}if(presentation.FrameFailure!=null){LastError=presentation.FrameFailure.GetBaseException().Message;State="Faulted";UpdateState();return;}if(!eyeUpdate.IsCompleted||lastReceipt==null||(long)lastReceipt["projection_revision"]<requestedEyeRevision)return;float x=0,y=0;if(eyes.SelectedIndex==1&&mouseInside){x=mouseX;y=mouseY;}else if(eyes.SelectedIndex==2){x=(float)Math.Sin(clock.Elapsed.TotalSeconds)*.12f;y=(float)Math.Cos(clock.Elapsed.TotalSeconds*.7)*.06f;}if(Math.Abs(x-lastX)<.001f&&Math.Abs(y-lastY)<.001f)return;lastX=x;lastY=y;try{eyeUpdate=ObserveEye(presentation.SetEyeAsync(x,y,-.6f,false));requestedEyeRevision=presentation.RequestedProjectionRevision;}catch(Exception error){LastError=error.Message;State="Faulted";UpdateState();}}
